func (fx *SubscriberSubscriptionTestSuiteConfig) nextParent(t *testing.T, pristine bool) string {
	if pristine {
		fx.currParent++
	}
	if fx.currParent >= len(fx.Parents) {
		t.Fatal("need at least", fx.currParent+1, "parents")
	}
	return fx.Parents[fx.currParent]
}

func (fx *SubscriberSubscriptionTestSuiteConfig) peekNextParent(t *testing.T) string {
	next := fx.currParent + 1
	if next >= len(fx.Parents) {
		t.Fatal("need at least", next+1, "parents")
	}
	return fx.Parents[next]
}

func (fx *SubscriberSubscriptionTestSuiteConfig) maybeSkip(t *testing.T) {
	for _, skip := range fx.Skip {
		if strings.Contains(t.Name(), skip) {
			t.Skip("skipped because of .Skip")
		}
	}
}

func (fx *SubscriberSubscriptionTestSuiteConfig) normalize(msg *Subscription) *Subscription {
	if fx.Normalize == nil || msg == nil {
		return msg
	}
	normalized := proto.Clone(msg).(*Subscription)
	fx.Normalize(normalized)
	return normalized
}

func (fx *SubscriberSubscriptionTestSuiteConfig) normalizeAll(msgs []*Subscription) []*Subscription {
	if fx.Normalize == nil {
		return msgs
	}
	normalized := make([]*Subscription, len(msgs))
	for i, msg := range msgs {
		normalized[i] = fx.normalize(msg)
	}
	return normalized
}

func (fx *SubscriberSubscriptionTestSuiteConfig) listed(t *testing.T, parent string, want, got []*Subscription) []*Subscription {
	t.Helper()
	assert.Equal(t, len(want)+fx.Preexisting, len(got), "listed resources, with Preexisting")
	names := make(map[string]bool, len(want))
	for _, msg := range want {
		names[msg.GetName()] = true
	}
	created := make([]*Subscription, 0, len(want))
	for _, msg := range got {
		assert.Check(t, strings.HasPrefix(msg.GetName(), parent+"/"), "listed resource is not under the parent")
		if names[msg.GetName()] {
			created = append(created, msg)
		}
	}
	return created
}

func (fx *SubscriberSubscriptionTestSuiteConfig) create(t *testing.T, parent string) *Subscription {
	t.Helper()
	if fx.CreateResource == nil {
		t.Skip("Test skipped because CreateResource not specified on SubscriberSubscriptionTestSuiteConfig")
	}
	created, err := fx.CreateResource(fx.Context(), parent)
	assert.NilError(t, err)
	return created
}

func (fx *SubscriberSubscriptionTestSuiteConfig) notFoundName(name string) string {
	// appending to the resource name ensures it is valid
	return name + "notfound"
}

func (fx *SubscriberSubscriptionTestSuiteConfig) field(msg *Subscription, name protoreflect.Name) *Subscription {
	msg = fx.normalize(msg)
	fd := msg.ProtoReflect().Descriptor().Fields().ByName(name)
	only := &Subscription{}
	if msg.ProtoReflect().Has(fd) {
		only.ProtoReflect().Set(fd, msg.ProtoReflect().Get(fd))
	}
	return only
}

func (fx *SubscriberSubscriptionTestSuiteConfig) withoutField(msg *Subscription, name protoreflect.Name) *Subscription {
	cleared := proto.Clone(msg).(*Subscription)
	cleared.ProtoReflect().Clear(cleared.ProtoReflect().Descriptor().Fields().ByName(name))
	return cleared
}
